class Solution {
public:
    vector<int> maxPrimes(int n, int s) {
        vector<bool> prime(n + 1, true);
        prime[0] = false;
        if (n >= 1) prime[1] = false;
        for (int p = 2; 1LL * p * p <= n; ++p) {
            if (prime[p]) for (int x = p * p; x <= n; x += p) prime[x] = false;
        }
        vector<int> ans;
        long long sum = 0;
        for (int p = 2; p <= n; ++p) {
            if (!prime[p]) continue;
            if (sum + p > s) break;
            sum += p;
            ans.push_back(p);
        }
        return ans;
    }
};
